public class ReceiptSink {
  public static void receive(List<SObject> events) {
    if (!Test.isRunningTest()) return;
    List<SignalReceipt__c> receipts = new List<SignalReceipt__c>();
    for(SObject event : events) {
      Schema.SObjectField token=event.getSObjectType().getDescribe().fields.getMap().get('CreatedDate');
      Object named=event.get('CreatedDate'), tokenValue=event.get(token);
      receipts.add(new SignalReceipt__c(Name=(String)event.get('Note__c'),
        DateKnown__c=named!=null, Consistent__c=named==tokenValue,
        ReplayKnown__c=event.get('ReplayId')!=null));
    }
    insert as system receipts;
  }
  public static String receipt(String key) {
    List<SignalReceipt__c> rows=[SELECT DateKnown__c,Consistent__c,ReplayKnown__c
      FROM SignalReceipt__c WHERE Name=:key WITH SYSTEM_MODE];
    if(rows.isEmpty()) return '0';
    return rows.size()+'/'+rows[0].DateKnown__c+'/'+rows[0].Consistent__c+'/'+rows[0].ReplayKnown__c;
  }
  public static String caller(SObject event) {
    Boolean fresh=event.get('CreatedDate')==null && event.get('ReplayId')==null;
    Database.SaveResult result=EventBus.publish(event);
    return fresh+'/'+result.isSuccess()+'/'+(event.get('CreatedDate')==null)+'/'+(event.get('ReplayId')==null);
  }
}

